files.content:
.root { --marker: 1.75rem; --halo: 4px; min-width: 0; color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); }
/* A horizontal stepper spans its container, so it can safely measure itself and fold into markers when space runs out. */
.horizontal { width: 100%; container: stepper / inline-size; }
.list { display: grid; margin: 0; padding: 0; list-style: none; }
.item { position: relative; min-width: 0; }
.horizontal .item:not(:last-child) { padding-inline-end: var(--space-4); }
.vertical .item:not(:last-child) { padding-bottom: var(--space-5); }
.compact.vertical .item:not(:last-child) { padding-bottom: var(--space-6); }

/* Buttons and spans share one head, so a chosen step keeps focus as it becomes the current one. */
.head { display: grid; margin: 0; padding: 0; border: 0; border-radius: var(--space-2); background: none; color: inherit; font: inherit; letter-spacing: inherit; text-align: start; cursor: default; -webkit-tap-highlight-color: transparent; }
.head[data-clickable] { cursor: pointer; }
.horizontal .head { width: fit-content; max-width: 100%; justify-items: start; row-gap: var(--space-3); }
.vertical .head { width: 100%; grid-template-columns: var(--marker) minmax(0, 1fr); column-gap: var(--space-3); align-items: start; }
.compact.vertical .head { grid-template-columns: var(--marker); column-gap: 0; }
.head:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 4px; }
.head:focus:not(:focus-visible) { outline: none; }

/* The ring sits behind the disc and grows out of it; the disc carries the state color and the glyph. */
.marker { position: relative; display: grid; width: var(--marker); height: var(--marker); flex: none; place-items: center; }
.ring { position: absolute; inset: calc(var(--halo) * -1); border-radius: var(--radius-pill); background: var(--accent-subtle); transition: background-color var(--duration-standard) var(--ease-standard); }
.disc { position: relative; display: grid; width: 100%; height: 100%; place-items: center; border-radius: var(--radius-pill); background: var(--surface); box-shadow: inset 0 0 0 1px var(--border-strong); color: var(--text-muted); font-size: var(--text-xs); font-weight: 500; font-variant-numeric: tabular-nums; line-height: 1; transition: background-color var(--duration-standard) var(--ease-standard), box-shadow var(--duration-standard) var(--ease-standard), color var(--duration-standard) var(--ease-standard), transform var(--duration-spring) var(--ease-spring); }
.glyph { display: grid; grid-area: 1 / 1; place-items: center; }
.icon { width: .875rem; height: .875rem; }
.item[data-status="current"] .disc { box-shadow: inset 0 0 0 1.5px var(--accent); color: var(--foreground); }
.item[data-status="complete"] .disc { background: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); color: var(--accent-foreground); }
.item[data-status="error"] .disc { background: color-mix(in oklch, var(--danger) 10%, var(--surface)); box-shadow: inset 0 0 0 1.5px var(--danger); color: var(--danger); }
.item[data-status="error"] .ring { background: color-mix(in oklch, var(--danger) 16%, transparent); }

/* The track stays put; only the fill scales along it on a spring, from the step that was just finished. */
.connector { position: absolute; overflow: hidden; border-radius: var(--radius-pill); background: var(--border); pointer-events: none; }
.horizontal .connector { top: calc(var(--marker) / 2 - 1px); inset-inline: calc(var(--marker) + var(--halo) + var(--space-1)) calc(var(--halo) + var(--space-1)); height: 2px; }
/* Both ends keep a clear gap from the markers, and from the current step's ring. */
.vertical .connector { top: calc(var(--marker) + var(--halo) + 2px); bottom: calc(var(--halo) + 2px); inset-inline-start: calc(var(--marker) / 2 - 1px); width: 2px; }
.fill { position: absolute; inset: 0; border-radius: inherit; background: var(--accent); }
.horizontal .fill { transform-origin: left center; }
.horizontal .fill:dir(rtl) { transform-origin: right center; }
.vertical .fill { transform-origin: center top; }

.text { display: grid; min-width: 0; }
/* Centers the first line of the label on the marker. */
.vertical .text { padding-top: .25rem; }
.label { display: block; color: var(--text-muted); font-size: var(--text-sm); font-weight: 500; line-height: 1.25rem; overflow-wrap: break-word; transition: color var(--duration-standard) var(--ease-standard); }
.item[data-status="complete"] .label { color: var(--text-secondary); }
.item[data-status="current"] .label, .item[data-status="error"] .label { color: var(--foreground); }
/* Changing text pops out of flow against this box while it leaves, so it must be the positioned parent. */
.slot { display: block; }
.slotInner { position: relative; display: block; }
.description, .error { display: block; padding-top: 2px; font-size: var(--text-xs); font-weight: 400; line-height: var(--leading-body); overflow-wrap: break-word; }
.description { color: var(--text-muted); }
.error { color: var(--danger); }

.caption { display: none; margin-top: var(--space-3); }
.captionLabel { display: block; color: var(--foreground); font-size: var(--text-sm); font-weight: 500; line-height: 1.25rem; }

@media (hover: hover) and (pointer: fine) {
  .head[data-clickable]:hover .label { color: var(--foreground); }
  .item[data-status="complete"] .head[data-clickable]:hover .disc { background: var(--accent-strong); box-shadow: inset 0 0 0 1px var(--accent-strong); }
  .item[data-status="error"] .head[data-clickable]:hover .disc { background: color-mix(in oklch, var(--danger) 18%, var(--surface)); }
}
.head[data-clickable]:active .disc { transform: scale(.92); }

.srOnly, .compact .text { position: absolute; width: 1px; height: 1px; margin: 0; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.compact.horizontal .caption { display: grid; }
/* Four labels no longer fit side by side: keep the markers and name the current step underneath. */
@container stepper (max-width: 30rem) {
  .horizontal .text { position: absolute; width: 1px; height: 1px; margin: 0; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .horizontal .caption { display: grid; }
}

@media (prefers-reduced-motion: reduce) {
  .disc, .ring, .label { transition: none; }
  .head[data-clickable]:active .disc { transform: none; }
}
